Here is a shape to build from:

def intro():
    print("Welcome to the adventure!")

def choose_weapon():
    weapon = input("Pick a weapon — sword or staff: ")
    if weapon == "sword":
        print("You grab the gleaming sword.")
    else:
        print("You raise your magic staff.")

def battle():
    for i in range(1, 4):
        print("Round", i, "— you strike!")
    print("The enemy falls.")

def ending():
    print("You win! The dungeon is clear.")

intro()
choose_weapon()
battle()
ending()
